-- Permission vocabulary and system roles of the notification module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the notification permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('notification:create'::text, 'notification'::text, 'create'::text, 'Create notification'::text),
            ('notification:delete'::text, 'notification'::text, 'delete'::text, 'Delete notification'::text),
            ('notification:purge'::text, 'notification'::text, 'purge'::text, 'Purge notification'::text),
            ('notification:read'::text, 'notification'::text, 'read'::text, 'Read notification'::text),
            ('notification:restore'::text, 'notification'::text, 'restore'::text, 'Restore notification'::text),
            ('notification:update'::text, 'notification'::text, 'update'::text, 'Update notification'::text),
            ('notification_template:create'::text, 'notification_template'::text, 'create'::text, 'Create notification template'::text),
            ('notification_template:delete'::text, 'notification_template'::text, 'delete'::text, 'Delete notification template'::text),
            ('notification_template:purge'::text, 'notification_template'::text, 'purge'::text, 'Purge notification template'::text),
            ('notification_template:read'::text, 'notification_template'::text, 'read'::text, 'Read notification template'::text),
            ('notification_template:restore'::text, 'notification_template'::text, 'restore'::text, 'Restore notification template'::text),
            ('notification_template:update'::text, 'notification_template'::text, 'update'::text, 'Update notification template'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('notification:create'::text, 'notification'::text, 'create'::text, 'Create notification'::text),
            ('notification:delete'::text, 'notification'::text, 'delete'::text, 'Delete notification'::text),
            ('notification:purge'::text, 'notification'::text, 'purge'::text, 'Purge notification'::text),
            ('notification:read'::text, 'notification'::text, 'read'::text, 'Read notification'::text),
            ('notification:restore'::text, 'notification'::text, 'restore'::text, 'Restore notification'::text),
            ('notification:update'::text, 'notification'::text, 'update'::text, 'Update notification'::text),
            ('notification_template:create'::text, 'notification_template'::text, 'create'::text, 'Create notification template'::text),
            ('notification_template:delete'::text, 'notification_template'::text, 'delete'::text, 'Delete notification template'::text),
            ('notification_template:purge'::text, 'notification_template'::text, 'purge'::text, 'Purge notification template'::text),
            ('notification_template:read'::text, 'notification_template'::text, 'read'::text, 'Read notification template'::text),
            ('notification_template:restore'::text, 'notification_template'::text, 'restore'::text, 'Restore notification template'::text),
            ('notification_template:update'::text, 'notification_template'::text, 'update'::text, 'Update notification template'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
